        private async Task PopulateDashboardHardwareRowAsync(SystemSummary s)
        {
            // ── Storage — show capacity big + model below (like RAM card) ────────
            if (_allDisks.Count > 0)
            {
                long totalBytes = _allDisks.Sum(d =>
                {
                    if (!string.IsNullOrEmpty(d.Size))
                    {
                        var parts = d.Size.Split(' ');
                        if (parts.Length >= 2 && double.TryParse(parts[0], out double sz))
                            return (long)(sz * (parts[1].StartsWith("T") ? 1000 : 1));
                    }
                    return 0L;
                });
                string cap = totalBytes >= 900 ? $"{totalBytes / 1000.0:F1} TB"
                           : totalBytes > 0    ? $"{totalBytes} GB"
                           : _allDisks[0].Size;
                TxtStorageDash.Text = cap;
                if (FindName("TxtStorageDash2") is System.Windows.Controls.TextBlock sd2x) sd2x.Text = cap;
                var model = (_allDisks[0].Model ?? "").Replace("SAMSUNG", "Samsung")
                    .Replace("WESTERN DIGITAL", "WD").Replace("_", " ").Trim();
                TxtStorageSub.Text = model.Length > 14 ? model[..14] + "…" : model;
            }
            else
            {
                // WMI fallback — run on background thread to avoid UI freeze
                string dashText = "—", subText = "";
                try
                {
                    (dashText, subText) = await Task.Run(() =>
                    {
                        using var searcher = SMDWin.Services.WmiHelper.Searcher(
                            "SELECT Model, Size FROM Win32_DiskDrive ORDER BY DeviceID", System.TimeSpan.FromSeconds(10));
                        using var __wmiDisks = searcher.Get();
                        var disks = __wmiDisks.Cast<System.Management.ManagementObject>().ToList();
                        if (disks.Count == 0) return ("—", "");
                        long totalGB = disks.Sum(d => Convert.ToInt64(d["Size"] ?? 0L) / 1_073_741_824L);
                        int[] std = { 32, 64, 120, 128, 240, 256, 480, 512, 960, 1000, 2000 };
                        int rounded = std.OrderBy(x => Math.Abs(x - (int)totalGB)).First();
                        string dash = rounded >= 1000 ? $"{rounded / 1000.0:F1} TB" : $"{rounded} GB";
                        string mdl  = disks[0]["Model"]?.ToString() ?? "—";
                        string sub  = mdl.Length > 22 ? mdl[..22] + "…" : mdl;
                        return (dash, sub);
                    });
                }
                catch (Exception ex) { AppLogger.Warning(ex, "PopulateDashboardHardwareRowAsync: WMI disk fallback"); }
                TxtStorageDash.Text = dashText;
                if (FindName("TxtStorageDash2") is System.Windows.Controls.TextBlock sd2y) sd2y.Text = dashText;
                TxtStorageSub.Text  = subText;
            }

            // ── Network card ──────────────────────────────────────────────────
            _ = PopulateNetCardAsync();
        }
    }
